function normaliseImportedRoutines(value) {
  if (!Array.isArray(value)) return [];
  return value.filter(item => item && typeof item.name === "string" && Array.isArray(item.steps))
    .map((item, index) => ({
      id: `import-${Date.now()}-${index}-${Math.random().toString(36).slice(2,7)}`,
      name: item.name.trim().slice(0,60),
      steps: item.steps.filter(step => typeof step === "string").map(step => step.trim()).filter(Boolean).slice(0,10).map(step => step.slice(0,120))
    }))
    .filter(item => item.name && item.steps.length)
    .slice(0,50);
}
