$("#export-encrypted-routines").addEventListener("click", async () => {
  const passphrase = $("#backup-passphrase").value;
  if (passphrase.length < 12) {
    $("#custom-routine-status").textContent = t("encryptedBackupError");
    return;
  }
  if (!customRoutines.length) {
    $("#custom-routine-status").textContent = t("encryptedBackupEmpty");
    return;
  }
  try {
    const { encryptJson } = await import("./secure-storage.js");
    const payload = { format:"project-n-01-routines", version:1, routines:customRoutines.map(({name,steps})=>({name,steps})) };
    const encrypted = await encryptJson(payload, passphrase);
    const blob = new Blob([JSON.stringify(encrypted, null, 2)], {type:"application/json"});
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = "novalife-routines-encrypted.json";
    document.body.append(link);
    link.click();
    link.remove();
    window.setTimeout(() => URL.revokeObjectURL(url), 1000);
    $("#custom-routine-status").textContent = t("encryptedBackupSuccess");
  } catch {
    $("#custom-routine-status").textContent = t("encryptedBackupError");
  } finally {
    $("#backup-passphrase").value = "";
  }
});
$("#import-encrypted-routines").addEventListener("change", async event => {
  let unlockedForThisImport = false;
  const file = event.target.files && event.target.files[0];
  if (!file) return;
  const passphrase = $("#backup-passphrase").value;
  const confirmPassphrase = $("#confirm-vault-passphrase").value;
  $("#backup-passphrase").value = "";
  $("#confirm-vault-passphrase").value = "";
  try {
    if (file.size > 1024 * 1024) throw new Error("too-large");
    if (passphrase.length < 12) throw new Error("passphrase");
    const { decryptJson } = await import("./secure-storage.js");
    const parsed = await decryptJson(JSON.parse(await file.text()), passphrase);
    let candidates;
    if (parsed && parsed.format === "project-n-01-routines" && parsed.version === 1 && Array.isArray(parsed.routines)) {
      candidates = parsed.routines;
    } else if (parsed && Array.isArray(parsed.routines)) {
      // Also accept the encrypted-vault envelope exported by the vault activation flow.
      candidates = parsed.routines;
    } else {
      throw new Error("invalid");
    }
    const validCandidateCount = candidates.filter(item =>
      item && typeof item.name === "string" && Array.isArray(item.steps) &&
      item.name.trim() && item.steps.some(step => typeof step === "string" && step.trim())
    ).length;
    if (validCandidateCount > 50) {
      $("#custom-routine-status").textContent = t("routineImportLimit");
      return;
    }
    const imported = normaliseImportedRoutines(candidates);
    if (!imported.length) throw new Error("invalid");
    const { EncryptedVault } = await import("./encrypted-vault.js");
    const previous = customRoutines;
    if (encryptedVaultExists && (!activeVault || !activeVault.isUnlocked)) {
      const vault = new EncryptedVault(localStorage);
      const existing = await vault.unlock(passphrase);
      if (!existing || !Array.isArray(existing.routines)) throw new Error("invalid-vault-data");
      activeVault = vault;
      unlockedForThisImport = true;
      customRoutines = normaliseImportedRoutines(existing.routines);
    }
    if (customRoutines.length + imported.length > 50) {
      throw new Error("routine-limit");
    }
    const merged = [...customRoutines, ...imported];
    if (encryptedVaultExists) {
      customRoutines = merged;
      if (!(await saveCustomRoutines())) {
        customRoutines = previous;
        throw new Error("storage");
      }
    } else {
      if (passphrase !== confirmPassphrase) {
        $("#custom-routine-status").textContent = t("vaultPassphraseMismatch");
        return;
      }
      const vault = new EncryptedVault(localStorage);
      await vault.initialize(passphrase, { routines: merged });
      activeVault = vault;
      encryptedVaultExists = true;
      customRoutines = merged;
    }
    updateVaultControls();
    scheduleVaultAutoLock();
    renderCustomRoutines();
    $("#custom-routine-status").textContent = t("encryptedBackupSuccess");
  } catch (error) {
    if (unlockedForThisImport && activeVault) {
      activeVault.lock();
      activeVault = null;
      customRoutines = [];
      updateVaultControls();
      renderCustomRoutines();
    }
    $("#custom-routine-status").textContent = error?.message === "routine-limit"
      ? t("routineImportLimit") : t("encryptedBackupError");
  } finally {
    event.target.value = "";
  }
});

$("#migrate-routines-to-vault").addEventListener("click", async () => {
  const passphrase = $("#backup-passphrase").value;
  const confirmPassphrase = $("#confirm-vault-passphrase").value;
  const status = $("#vault-migration-status");
  if (passphrase.length < 12) {
    status.textContent = t("vaultMigrationError");
    return;
  }
  const button = $("#migrate-routines-to-vault");
  button.disabled = true;
  $("#backup-passphrase").value = "";
  $("#confirm-vault-passphrase").value = "";
  let vault;
  let activated = false;
  try {
    const [{ EncryptedVault }, { migrateLegacyRoutines, readLegacyRoutines }] = await Promise.all([
      import("./encrypted-vault.js"),
      import("./routine-migration.js")
    ]);
    vault = new EncryptedVault(localStorage);
    if (localStorage.getItem(encryptedVaultStorageKey) !== null) {
      const data = await vault.unlock(passphrase);
      if (!data || !Array.isArray(data.routines)) throw new Error("invalid-vault-data");
    } else {
      if (passphrase !== confirmPassphrase) {
        status.textContent = t("vaultPassphraseMismatch");
        return;
      }
      const preview = readLegacyRoutines(localStorage);
      if (preview.found && preview.routines.length) {
        await migrateLegacyRoutines({ storage:localStorage, vault, passphrase });
      } else {
        await vault.initialize(passphrase, { routines: customRoutines });
      }
    }
    activeVault = vault;
    encryptedVaultExists = true;
    const data = activeVault.read();
    customRoutines = Array.isArray(data.routines) ? data.routines : [];
    activated = true;
    updateVaultControls();
    renderCustomRoutines();
    scheduleVaultAutoLock();
    const envelope = activeVault.exportEnvelope();
    const blob = new Blob([JSON.stringify(envelope, null, 2)], {type:"application/json"});
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = "novalife-encrypted-vault.json";
    document.body.append(link);
    link.click();
    link.remove();
    window.setTimeout(() => URL.revokeObjectURL(url), 1000);
    status.textContent = t("vaultUnlocked");
  } catch {
    status.textContent = t("vaultMigrationError");
  } finally {
    if (!activated && vault) vault.lock();
    button.disabled = false;
  }
});

