$("#breath-stop").addEventListener("click", () => stopBreathing(true));
const tips = {senses:"tipSenses",quiet:"tipQuiet",water:"tipWater"};
$$("[data-calm-tip]").forEach(button => button.addEventListener("click", () => { $("#calm-tip-text").textContent = t(tips[button.dataset.calmTip]); }));
const phrases = {break:"phraseBreakText",help:"phraseHelpText",slow:"phraseSlowText",no:"phraseNoText"};
$$("[data-phrase]").forEach(button => button.addEventListener("click", () => {
  $("#phrase-output").hidden = false;
  $("#phrase-output-text").textContent = t(phrases[button.dataset.phrase]);
  $("#phrase-output").scrollIntoView({behavior:document.body.classList.contains("reduced-motion") ? "auto" : "smooth",block:"nearest"});
  $("#close-phrase").focus();
}));
$("#close-phrase").addEventListener("click", () => { $("#phrase-output").hidden = true; });
$("#speak-phrase").addEventListener("click", () => {
  const phrase = $("#phrase-output-text").textContent;
  if (!("speechSynthesis" in window) || !("SpeechSynthesisUtterance" in window)) { showToast(t("readUnavailable")); return; }
  try {
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(phrase);
    utterance.lang = language === "nl" ? "nl-NL" : "en-GB";
    window.speechSynthesis.speak(utterance);
  } catch { showToast(t("readError")); }
});
const noteCharacterCount = $("#note-character-count");
function updateNoteCharacterCount() {
  noteCharacterCount.textContent = t("noteCharacterCount").replace("{count}", String($("#note-text").value.length));
}
$("#note-text").addEventListener("input", updateNoteCharacterCount);
updateNoteCharacterCount();
$("#download-text-note").addEventListener("click", () => {
  const note = $("#note-text").value;
  if (!note.trim()) {
    $("#note-status").textContent = t("noteTextEmpty");
    return;
  }
  let url;
  try {
    const blob = new Blob([note], {type:"text/plain;charset=utf-8"});
    url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = language === "nl" ? "mijn-notitie.txt" : "my-note.txt";
    link.hidden = true;
    document.body.append(link);
    link.click();
    link.remove();
    $("#note-status").textContent = t("noteTextDownloaded");
  } catch {
    $("#note-status").textContent = t("noteTextEmpty");
  } finally {
    if (url) window.setTimeout(() => URL.revokeObjectURL(url), 1000);
  }
});
$("#copy-text-note").addEventListener("click", async () => {
  const note = $("#note-text").value;
  if (!note.trim()) {
    $("#note-status").textContent = t("noteCopyEmpty");
    return;
  }
  try {
    if (!navigator.clipboard || typeof navigator.clipboard.writeText !== "function") throw new Error("Clipboard API unavailable");
    await navigator.clipboard.writeText(note);
    $("#note-status").textContent = t("noteCopied");
  } catch {
    $("#note-text").focus();
    $("#note-text").select();
    $("#note-status").textContent = t("noteCopyFallback");
  }
});
$("#clear-note").addEventListener("click", () => {
  $("#note-text").value = "";
  updateNoteCharacterCount();
  $("#note-status").textContent = t("noteCleared");
  $("#note-text").focus();
});

// Explicit, in-memory voice notes: nothing is persisted or uploaded by this app.
const voiceNoteStart = $("#start-voice-note");
const voiceNoteStop = $("#stop-voice-note");
const voiceNoteDownload = $("#download-voice-note");
const voiceNotePlayback = $("#voice-note-playback");
const voiceNoteStatus = $("#voice-note-status");
let voiceRecorder = null;
let voiceStream = null;
let voiceChunks = [];
let voiceBlob = null;
let voiceObjectUrl = null;
function releaseVoiceStream() {
  if (voiceStream) voiceStream.getTracks().forEach(track => track.stop());
  voiceStream = null;
}
function clearVoiceObjectUrl() {
  if (voiceObjectUrl) URL.revokeObjectURL(voiceObjectUrl);
  voiceObjectUrl = null;
}
voiceNoteStart.addEventListener("click", async () => {
  if (!navigator.mediaDevices?.getUserMedia || typeof MediaRecorder === "undefined") {
    voiceNoteStatus.textContent = t("recordingUnsupported");
    return;
  }
  voiceNoteStart.disabled = true;
  voiceNoteStatus.textContent = "";
  try {
    voiceStream = await navigator.mediaDevices.getUserMedia({audio:true});
    voiceChunks = [];
    voiceBlob = null;
    clearVoiceObjectUrl();
    voiceNotePlayback.pause();
    voiceNotePlayback.removeAttribute("src");
    voiceNotePlayback.hidden = true;
    voiceNoteDownload.disabled = true;
    voiceRecorder = new MediaRecorder(voiceStream);
    voiceRecorder.addEventListener("dataavailable", event => {
      if (event.data && event.data.size) voiceChunks.push(event.data);
    });
    voiceRecorder.addEventListener("error", () => {
      voiceNoteStatus.textContent = t("recordingError");
      voiceNoteStart.disabled = false;
      voiceNoteStop.disabled = true;
      releaseVoiceStream();
    });
    voiceRecorder.addEventListener("stop", () => {
      voiceBlob = new Blob(voiceChunks, {type:voiceRecorder.mimeType || "audio/webm"});
      voiceChunks = [];
      releaseVoiceStream();
      voiceNoteStart.disabled = false;
      voiceNoteStop.disabled = true;
      if (!voiceBlob.size) {
        voiceNoteStatus.textContent = t("recordingError");
        return;
      }
      voiceObjectUrl = URL.createObjectURL(voiceBlob);
      voiceNotePlayback.src = voiceObjectUrl;
      voiceNotePlayback.hidden = false;
      voiceNoteDownload.disabled = false;
      voiceNoteStatus.textContent = t("recordingStopped");
    }, {once:true});
    voiceRecorder.start();
    voiceNoteStop.disabled = false;
    voiceNoteStatus.textContent = t("recordingStarted");
  } catch {
    releaseVoiceStream();
    voiceNoteStart.disabled = false;
    voiceNoteStop.disabled = true;
    voiceNoteStatus.textContent = t("recordingPermissionError");
  }
});
voiceNoteStop.addEventListener("click", () => {
  if (voiceRecorder && voiceRecorder.state !== "inactive") {
    voiceRecorder.stop();
    voiceNoteStatus.textContent = t("recordingStopped");
  }
});
voiceNoteDownload.addEventListener("click", () => {
  if (!voiceBlob?.size || !voiceObjectUrl) {
    voiceNoteStatus.textContent = t("recordingEmpty");
    return;
  }
  const link = document.createElement("a");
  link.href = voiceObjectUrl;
  const audioExtension = voiceBlob.type.includes("mp4") ? "mp4" : voiceBlob.type.includes("ogg") ? "ogg" : voiceBlob.type.includes("wav") ? "wav" : "webm";
  link.download = "spraaknotitie." + audioExtension;
  link.hidden = true;
  document.body.append(link);
  link.click();
  link.remove();
});
window.addEventListener("pagehide", () => {
  if (voiceRecorder && voiceRecorder.state !== "inactive") voiceRecorder.stop();
  releaseVoiceStream();
  clearVoiceObjectUrl();
}, {once:true});


// Optional browser speech recognition. Recognition may use a browser/provider service;
// only final recognized text is appended to the note field, never auto-saved by this prototype.
const dictationStart = $("#start-speech-to-text");
const dictationStop = $("#stop-speech-to-text");
const dictationStatus = $("#speech-to-text-status");
const noteTextField = $("#note-text");
const SpeechRecognitionAPI = window.SpeechRecognition || window.webkitSpeechRecognition;
let dictationRecognition = null;
let dictationHadResult = false;
function setDictationButtons(listening) {
  dictationStart.disabled = listening || !SpeechRecognitionAPI;
  dictationStop.disabled = !listening;
}
if (!SpeechRecognitionAPI) {
  dictationStart.disabled = true;
  dictationStatus.textContent = t("dictationUnsupported");
}
dictationStart.addEventListener("click", () => {
  if (!SpeechRecognitionAPI) {
    dictationStatus.textContent = t("dictationUnsupported");
    return;
  }
  try {
    dictationRecognition = new SpeechRecognitionAPI();
    dictationRecognition.lang = language === "nl" ? "nl-NL" : "en-GB";
    dictationRecognition.continuous = true;
    dictationRecognition.interimResults = false;
    dictationHadResult = false;
    dictationRecognition.addEventListener("start", () => {
      setDictationButtons(true);
      dictationStatus.textContent = t("dictationStarted");
    });
    dictationRecognition.addEventListener("result", event => {
      const phrases = [];
      for (let i = event.resultIndex; i < event.results.length; i++) {
        if (event.results[i].isFinal) {
          const transcript = event.results[i][0]?.transcript?.trim();
          if (transcript) phrases.push(transcript);
        }
      }
      if (phrases.length) {
        const addition = phrases.join(" ");
        noteTextField.value = noteTextField.value.trim()
          ? noteTextField.value.replace(/\s+$/, "") + " " + addition
          : addition;
        noteTextField.dispatchEvent(new Event("input", {bubbles:true}));
        dictationHadResult = true;
        dictationStatus.textContent = t("dictationAdded");
      }
    });
    dictationRecognition.addEventListener("error", event => {
      dictationStatus.textContent = event.error === "not-allowed" || event.error === "service-not-allowed"
        ? t("dictationPermissionError") : t("dictationError");
    });
    dictationRecognition.addEventListener("end", () => {
      setDictationButtons(false);
      if (!dictationHadResult && !dictationStatus.textContent.includes(t("dictationPermissionError")) &&
          !dictationStatus.textContent.includes(t("dictationError"))) {
        dictationStatus.textContent = t("dictationNoResult");
      } else if (dictationHadResult && dictationStatus.textContent === t("dictationStarted")) {
        dictationStatus.textContent = t("dictationStopped");
      }
      dictationRecognition = null;
    });
    dictationRecognition.start();
  } catch {
    setDictationButtons(false);
    dictationStatus.textContent = t("dictationPermissionError");
    dictationRecognition = null;
  }
});
dictationStop.addEventListener("click", () => {
  if (dictationRecognition) {
    dictationRecognition.stop();
    dictationStop.disabled = true;
  }
});
window.addEventListener("pagehide", () => {
  if (dictationRecognition) {
    try { dictationRecognition.abort(); } catch {}
    dictationRecognition = null;
  }
}, {once:true});

// In-memory drawing pad: nothing is stored or uploaded.
const sketchCanvas = $("#sketch-canvas");
const sketchContext = sketchCanvas.getContext("2d");
let sketchDrawing = false;
let sketchPointer = {x: sketchCanvas.width / 2, y: sketchCanvas.height / 2};
function sketchPoint(event) {
  const rect = sketchCanvas.getBoundingClientRect();
  return {
    x: (event.clientX - rect.left) * sketchCanvas.width / rect.width,
    y: (event.clientY - rect.top) * sketchCanvas.height / rect.height
  };
}
function drawSketchLine(from, to) {
  sketchContext.beginPath();
  sketchContext.moveTo(from.x, from.y);
  sketchContext.lineTo(to.x, to.y);
  sketchContext.strokeStyle = "#b9a7ff";
  sketchContext.lineWidth = Number($("#brush-size").value) * (sketchCanvas.width / sketchCanvas.getBoundingClientRect().width);
  sketchContext.lineCap = "round";
  sketchContext.lineJoin = "round";
  sketchContext.stroke();
}
sketchCanvas.addEventListener("pointerdown", event => {
  sketchDrawing = true;
  sketchPointer = sketchPoint(event);
  sketchCanvas.setPointerCapture?.(event.pointerId);
});
sketchCanvas.addEventListener("pointermove", event => {
  if (!sketchDrawing) return;
  const next = sketchPoint(event);
  drawSketchLine(sketchPointer, next);
  sketchPointer = next;
  $("#sketch-status").textContent = t("sketchDrawn");
});
function endSketchPointer() { sketchDrawing = false; }
sketchCanvas.addEventListener("pointerup", endSketchPointer);
sketchCanvas.addEventListener("pointercancel", endSketchPointer);
sketchCanvas.addEventListener("keydown", event => {
  const deltas = {ArrowUp:[0,-8],ArrowDown:[0,8],ArrowLeft:[-8,0],ArrowRight:[8,0]};
  const delta = deltas[event.key];
  if (!delta) return;
  event.preventDefault();
  const next = {
    x: Math.max(0, Math.min(sketchCanvas.width, sketchPointer.x + delta[0])),
    y: Math.max(0, Math.min(sketchCanvas.height, sketchPointer.y + delta[1]))
  };
  if (!event.shiftKey) drawSketchLine(sketchPointer, next);
  sketchPointer = next;
  $("#sketch-status").textContent = t("sketchDrawn");
});
$("#clear-sketch").addEventListener("click", () => {
  sketchContext.clearRect(0, 0, sketchCanvas.width, sketchCanvas.height);
  $("#sketch-status").textContent = t("sketchCleared");
  sketchCanvas.focus();
});
$("#export-sketch").addEventListener("click", () => {
  try {
    const pixels = sketchContext.getImageData(0, 0, sketchCanvas.width, sketchCanvas.height).data;
    let hasDrawing = false;
    for (let index = 3; index < pixels.length; index += 4) {
      if (pixels[index] !== 0) { hasDrawing = true; break; }
    }
    if (!hasDrawing) {
      $("#sketch-status").textContent = t("sketchEmpty");
      sketchCanvas.focus();
      return;
    }
    sketchCanvas.toBlob(blob => {
      if (!blob) {
        $("#sketch-status").textContent = t("sketchExportError");
        return;
      }
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = "mijn-tekening.png";
      link.hidden = true;
      document.body.append(link);
      link.click();
      link.remove();
      window.setTimeout(() => URL.revokeObjectURL(url), 1000);
      $("#sketch-status").textContent = t("sketchExported");
      sketchCanvas.focus();
    }, "image/png");
  } catch {
    $("#sketch-status").textContent = t("sketchExportError");
  }
});
const preferenceKey = "project-n-01-preferences-v1";
function readPreferences() {
  try {
    const raw = localStorage.getItem(preferenceKey);
    return raw ? JSON.parse(raw) : {};
  } catch {
    return {};
  }
}
function savePreferences() {
  try {
    localStorage.setItem(preferenceKey, JSON.stringify({
      language,
      largeText: $("#large-text").checked,
      reducedMotion: $("#less-motion").checked,
      quietView: $("#quiet-view").checked
    }));
  } catch {
    // Preferences still work for this session if storage is unavailable.
  }
}
function applyPreferences() {
  const preferences = readPreferences();
  const systemPrefersReducedMotion = typeof window.matchMedia === "function" && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  const reducedMotion = typeof preferences.reducedMotion === "boolean" ? preferences.reducedMotion : systemPrefersReducedMotion;
  $("#large-text").checked = preferences.largeText === true;
  $("#less-motion").checked = reducedMotion;
  $("#quiet-view").checked = preferences.quietView === true;
  document.body.classList.toggle("large-text", $("#large-text").checked);
  document.body.classList.toggle("reduced-motion", $("#less-motion").checked);
  document.body.classList.toggle("quiet-view", $("#quiet-view").checked);
  applyLanguage(preferences.language === "en" ? "en" : "nl");
}
$("#large-text").addEventListener("change", event => {
  document.body.classList.toggle("large-text", event.target.checked);
  savePreferences();
});
$("#less-motion").addEventListener("change", event => {
  document.body.classList.toggle("reduced-motion", event.target.checked);
  savePreferences();
});
$("#quiet-view").addEventListener("change", event => {
  document.body.classList.toggle("quiet-view", event.target.checked);
  savePreferences();
});
$("#today-date").textContent = new Intl.DateTimeFormat("nl-NL", {weekday:"short",day:"numeric",month:"short"}).format(new Date());
restoreDailyProgress();
updateTaskCount();
for (const routine of builtInRoutineIds) updateRoutineProgress(routine);
applyPreferences();

// Offline support is enabled only on secure origins or localhost.
if ("serviceWorker" in navigator && (location.protocol === "https:" || location.hostname === "localhost" || location.hostname === "127.0.0.1")) {
  window.addEventListener("load", () => {
    navigator.serviceWorker.register("/service-worker.js").catch(() => {
      // The prototype remains usable if service workers are unavailable.
    });
  }, { once: true });
}
